-- =====================================================================
-- NDIP Phase D.1 — Geography Foundation
-- Migration: phase_d_00_geography.sql
-- =====================================================================
-- Additive only. No ALTER, no DROP, no modification of any existing
-- Phase A/B/C table. Safe to run multiple times (idempotent via
-- IF NOT EXISTS / ON CONFLICT DO NOTHING).
--
-- Hierarchy: ng_states -> ng_lgas -> ng_wards -> ng_polling_units
--
-- ID scheme (documented explicitly — see PHASE_D1_IMPLEMENTATION.md
-- "Known Assumptions"):
--   ng_states.id   — sequential 1-37, states in alphabetical order,
--                    FCT included as state 37. This is an NDIP-internal
--                    integer surrogate key, NOT a claimed replica of any
--                    single external numbering authority (INEC/NBS use
--                    different, inconsistent schemes). ng_states.code
--                    carries the real, verifiable ISO 3166-2:NG code
--                    (e.g. 'NG-LA' for Lagos) for external cross-reference.
--   ng_lgas.id     — sequential 1-774, grouped by state (alphabetical),
--                    LGAs alphabetical within state. Also an NDIP-internal
--                    surrogate key. Count verified programmatically:
--                    17+21+31+21+20+8+23+27+18+25+13+18+16+17+11+27+27+23+
--                    44+34+21+21+16+20+13+25+20+18+30+33+17+23+23+16+17+14+6
--                    = 774.
--   ng_wards.id / ng_polling_units.id — surrogate keys assigned at import
--                    time by the CSV seed pipeline (scripts/seed_geography_csv.py).
--                    No ward/PU data is hand-typed in this migration —
--                    see assumptions doc for why.
-- =====================================================================

BEGIN;

-- pg_trgm powers the partial-match search indexes below. Created best-effort:
-- caught broadly (not just insufficient_privilege) because this can also
-- fail with feature_not_supported if the contrib module simply isn't
-- installed on the server at all — either way, this is a nice-to-have,
-- not a reason to abort the states/LGA seed that follows.
DO $$
BEGIN
    CREATE EXTENSION IF NOT EXISTS pg_trgm;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'pg_trgm extension not created (%) — search will fall back to plain ILIKE without a trigram index', SQLERRM;
END
$$;

-- ─── ng_states ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS ng_states (
    id          INTEGER PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    code        VARCHAR(10)  NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_ng_states_name ON ng_states (name);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ng_states_code ON ng_states (code);

-- ─── ng_lgas ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS ng_lgas (
    id          INTEGER PRIMARY KEY,
    name        VARCHAR(150) NOT NULL,
    code        VARCHAR(20),
    state_id    INTEGER NOT NULL REFERENCES ng_states(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_ng_lgas_state_id ON ng_lgas (state_id);
CREATE INDEX IF NOT EXISTS ix_ng_lgas_name ON ng_lgas (name);
CREATE INDEX IF NOT EXISTS ix_ng_lgas_code ON ng_lgas (code);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ng_lgas_state_name ON ng_lgas (state_id, name);

-- ─── ng_wards ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS ng_wards (
    id          INTEGER PRIMARY KEY,
    name        VARCHAR(150) NOT NULL,
    code        VARCHAR(20),
    lga_id      INTEGER NOT NULL REFERENCES ng_lgas(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_ng_wards_lga_id ON ng_wards (lga_id);
CREATE INDEX IF NOT EXISTS ix_ng_wards_name ON ng_wards (name);
CREATE INDEX IF NOT EXISTS ix_ng_wards_code ON ng_wards (code);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ng_wards_lga_name ON ng_wards (lga_id, name);

-- ─── ng_polling_units ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS ng_polling_units (
    id          INTEGER PRIMARY KEY,
    name        VARCHAR(200) NOT NULL,
    code        VARCHAR(30),
    ward_id     INTEGER NOT NULL REFERENCES ng_wards(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_ng_polling_units_ward_id ON ng_polling_units (ward_id);
CREATE INDEX IF NOT EXISTS ix_ng_polling_units_name ON ng_polling_units (name);
CREATE INDEX IF NOT EXISTS ix_ng_polling_units_code ON ng_polling_units (code);

-- ─── Trigram search indexes (best-effort, depends on pg_trgm above) ───
DO $$
BEGIN
    CREATE INDEX IF NOT EXISTS ix_ng_states_name_search ON ng_states USING gin (name gin_trgm_ops);
    CREATE INDEX IF NOT EXISTS ix_ng_lgas_name_search ON ng_lgas USING gin (name gin_trgm_ops);
    CREATE INDEX IF NOT EXISTS ix_ng_wards_name_search ON ng_wards USING gin (name gin_trgm_ops);
    CREATE INDEX IF NOT EXISTS ix_ng_polling_units_name_search ON ng_polling_units USING gin (name gin_trgm_ops);
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Trigram GIN indexes skipped (%) — search falls back to plain ILIKE on the btree name indexes above', SQLERRM;
END
$$;

-- ─── Seed: 37 states, 774 LGAs (generated + count-verified, see header) ─
-- Auto-generated seed data for ng_states and ng_lgas
-- 37 states (36 alphabetical + FCT appended as #37), 774 LGAs. Verified count.


COMMIT;
